examples.template:
MonarchMediaUpload({{label}}, url: $cover, helper: {{description}}, maxImageSize: {{maxImageSize}}, videoUnavailable: {{videoUnavailable}}, labels: MonarchMediaUploadLabels(addImage: "Drop an image here", imageHint: { _ in "PNG, JPG, GIF or WebP up to 10 MB" })) { file, context in
    context.reportProgress(1)
    return MonarchMediaUploadResult(url: file.url)
}

